%{
  const props = entity.system.props;
  const pool = Number(props.athletik ?? 0) + Number(props.kraft ?? 0);
  if (pool <= 0) return `<strong>Athletik</strong>: Pool 0, kein Wurf möglich.`;
  const roll = await new Roll(pool + "d6").evaluate();
  const faces = roll.terms.at(0).results.map(r => r.result).sort((a,b) => a-b);
  let sechser = faces.filter(f => f === 6).length;
  let einser = faces.filter(f => f === 1).length;
  let kompetenzGenutzt = false;
  let facesVorKompetenz = null;
  if (einser > 0) {
    const kompetenzen = String(props.athletik_kompetenzen ?? "").trim();
    const hinweis = kompetenzen
      ? `Bekannte Kompetenzen fuer diese Fertigkeit: <strong>${kompetenzen}</strong><br>Deckt eine davon diese Handlung ab?`
      : `Deckt eine (ggf. noch nicht eingetragene) Kompetenz diese Handlung ab?`;
    kompetenzGenutzt = await Dialog.confirm({
      title: "Kompetenz nutzen?",
      content: `<p>${hinweis}<br>Dann darfst du einmal alle gewuerfelten 1er wiederholen (zweites Ergebnis bindend).</p>`,
    });
    if (kompetenzGenutzt) {
      facesVorKompetenz = faces.slice();
      const rerollRoll = await new Roll(einser + "d6").evaluate();
      const rerollFaces = rerollRoll.terms.at(0).results.map(r => r.result);
      let ri = 0;
      for (let i = 0; i < faces.length; i++) {
        if (faces[i] === 1) { faces[i] = rerollFaces[ri]; ri++; }
      }
      faces.sort((a, b) => a - b);
      sechser = faces.filter(f => f === 6).length;
      einser = faces.filter(f => f === 1).length;
    }
  }
  const vorher = Number(props.koerper_ausdauer ?? 0);
  const nachher = Math.max(0, vorher - 1);
  entity.update({"system.props.koerper_ausdauer": String(nachher)});
  let text = `<strong>Athletik</strong> (Pool ${pool}): (${faces.join(', ')})<br>Erfolge (6er): <strong>${sechser}</strong> &nbsp; Einser: <strong>${einser}</strong>`;
  if (kompetenzGenutzt) text += `<br><em>Kompetenz genutzt, 1er wiederholt (vorher: ${facesVorKompetenz.join(', ')})</em>`;
  if (einser >= 3) text += `<br>⚠️ Kritischer Misserfolg (3+ Einser)`;
  if (sechser >= 3) text += `<br>✨ Kritischer Erfolg (3+ Sechser)`;
  text += `<br><em>-1 Koerper-Ausdauer (jetzt ${nachher})</em>`;
  return text;
}%

